// Get the OpenAI response
const aiResponse = $json.output?.[0]?.content?.[0]?.text;

// Make sure the AI returned something
if (!aiResponse) {
  throw new Error("OpenAI did not return a classification.");
}

// If the response is a string, parse it.
// If structured output already returned an object, use it directly.
let classification;

if (typeof aiResponse === "string") {
  try {
    classification = JSON.parse(aiResponse);
  } catch (error) {
    throw new Error("Failed to parse OpenAI classification as JSON.");
  }
} else {
  classification = aiResponse;
}

// Extract and normalize the classification
const category = String(classification.category || "other").toLowerCase().trim();

const intent = String(classification.intent || "unknown").trim();

const urgency = String(classification.urgency || "medium").toLowerCase().trim();

const complexity = String(classification.complexity || "moderate").toLowerCase().trim();

const sentiment = String(classification.sentiment || "neutral").toLowerCase().trim();

const confidence = Number(classification.confidence ?? 0);

const aiAction = String(classification.action || "escalate").toLowerCase().trim();

const reason = String(classification.reason || "").trim();


// Business rules for escalation
const shouldEscalate =
  aiAction === "escalate" ||
  urgency === "critical" ||
  complexity === "complex" ||
  confidence < 0.75 ||
  category === "security";


// Determine final action
const finalAction = shouldEscalate ? "escalate" : "respond";


// Return clean data
return {
  json: {
    category,
    intent,
    urgency,
    complexity,
    sentiment,
    confidence,
    ai_action: aiAction,
    reason,
    final_action: finalAction
  }
};

const response = $input.first().json.output[0].content[0].text;

if (!response) {
  throw new Error("OpenAI did not return a customer response.");
}

return {
  json: {
    customer_name: $('Normalize Request').item.json.customer_name,
    customer_email: $('Normalize Request').item.json.customer_email,
    subject: $('Normalize Request').item.json.subject,
    category: $('Clean & Decide').item.json.category,
    intent: $('Clean & Decide').item.json.intent,
    response: response.trim()
  }
};

const urgency = $('Clean & Decide').item.json.urgency;

const priorityMap = {
  critical: 1,
  high: 2,
  medium: 3,
  low: 4
};

let escalationReason = $('Clean & Decide').item.json.reason;

if ($('Check FAQ').isExecuted) {
  const faqFound = $('Check FAQ').item.json.faq_found;

  if (faqFound === false) {
    escalationReason = "No matching knowledge base article found";
  }
}

return {
  json: {
    clickup_priority: priorityMap[urgency] || 3,
    escalation_reason: escalationReason
  }
};

const content = $json.content;

const faqFound =
  typeof content === "string" &&
  content.trim().length > 0;

return {
  json: {
    ...$json,
    faq_found: faqFound
  }
};

